import{_ as t,c as d,o as s,ae as o}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse(`{"title":"Get Checkout Addresses","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-checkout-addresses","title":"Get Checkout Addresses","description":"Retrieve the guest / authenticated customer's saved checkout addresses to select as shipping or billing address during checkout.","request":"GET /api/shop/checkout-addresses\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 281,\\n    \\"addressType\\": \\"cart_billing\\",\\n    \\"parentAddressId\\": null,\\n    \\"orderId\\": null,\\n    \\"firstName\\": \\"Jane\\",\\n    \\"lastName\\": \\"Doe\\",\\n    \\"gender\\": null,\\n    \\"companyName\\": null,\\n    \\"address\\": \\"12 Elm Street\\",\\n    \\"city\\": \\"New York\\",\\n    \\"state\\": \\"NY\\",\\n    \\"country\\": \\"US\\",\\n    \\"postcode\\": \\"10001\\",\\n    \\"email\\": \\"jane@example.com\\",\\n    \\"phone\\": \\"12125550111\\",\\n    \\"vatId\\": null,\\n    \\"defaultAddress\\": false,\\n    \\"useForShipping\\": false,\\n    \\"additional\\": null,\\n    \\"createdAt\\": \\"2026-08-07T17:27:28+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T17:27:28+05:30\\",\\n    \\"name\\": \\"Jane Doe\\"\\n  },\\n  {\\n    \\"id\\": 282,\\n    \\"addressType\\": \\"cart_shipping\\",\\n    \\"parentAddressId\\": null,\\n    \\"orderId\\": null,\\n    \\"firstName\\": \\"Jane\\",\\n    \\"lastName\\": \\"Doe\\",\\n    \\"gender\\": null,\\n    \\"companyName\\": null,\\n    \\"address\\": \\"12 Elm Street\\",\\n    \\"city\\": \\"New York\\",\\n    \\"state\\": \\"NY\\",\\n    \\"country\\": \\"US\\",\\n    \\"postcode\\": \\"10001\\",\\n    \\"email\\": \\"jane@example.com\\",\\n    \\"phone\\": \\"12125550111\\",\\n    \\"vatId\\": null,\\n    \\"defaultAddress\\": false,\\n    \\"useForShipping\\": false,\\n    \\"additional\\": null,\\n    \\"createdAt\\": \\"2026-08-07T17:27:28+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T17:27:28+05:30\\",\\n    \\"name\\": \\"Jane Doe\\"\\n  }\\n]\\n","commonErrors":[{"error":"Empty array","cause":"No checkout address has been saved on this cart yet","solution":"Save one with Set Checkout Address; an empty list is a 200, not an error"},{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/checkout/get-addresses.md","filePath":"api/rest-api/shop/checkout/get-addresses.md"}`),a={name:"api/rest-api/shop/checkout/get-addresses.md"};function r(n,e,i,c,l,h){return s(),d("div",null,e[0]||(e[0]=[o('<h1 id="get-checkout-addresses" tabindex="-1">Get Checkout Addresses <a class="header-anchor" href="#get-checkout-addresses" aria-label="Permalink to &quot;Get Checkout Addresses&quot;">​</a></h1><p>Retrieve guest / the authenticated customer&#39;s checkout saved addresses so they can select one as their shipping or billing address during checkout. This endpoint returns previously saved addresses — it does not create new ones.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/checkout-addresses</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The cart&#39;s own token as a Bearer token, or a logged-in customer&#39;s token.</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>A bare array of the addresses saved <strong>on this cart</strong> — typically two entries, the billing one and the shipping one, told apart by <code>addressType</code>. This is not the customer&#39;s address book; that is <a href="/api/rest-api/shop/customers/get-customer-addresses.html">Get Customer Addresses</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Address record ID.</td></tr><tr><td><code>addressType</code></td><td>string</td><td><code>cart_billing</code> or <code>cart_shipping</code>.</td></tr><tr><td><code>firstName</code> / <code>lastName</code> / <code>name</code></td><td>string</td><td>Recipient. <code>name</code> is the two joined.</td></tr><tr><td><code>address</code></td><td>string</td><td>Street address. Note the read returns <code>address</code>, while the save call takes <code>billingAddress</code> / <code>shippingAddress</code>.</td></tr><tr><td><code>city</code> / <code>state</code> / <code>country</code> / <code>postcode</code></td><td>string</td><td>Location.</td></tr><tr><td><code>email</code> / <code>phone</code></td><td>string</td><td>Contact details.</td></tr><tr><td><code>companyName</code> / <code>vatId</code> / <code>gender</code></td><td>string</td><td>Optional details, <code>null</code> when not supplied.</td></tr><tr><td><code>defaultAddress</code> / <code>useForShipping</code></td><td>boolean</td><td>Flags carried on the row; both read <code>false</code> on a cart address regardless of the <code>useForShipping</code> sent when saving.</td></tr><tr><td><code>parentAddressId</code></td><td>integer</td><td>The address-book entry this was copied from, <code>null</code> when typed in at checkout.</td></tr><tr><td><code>orderId</code></td><td>integer</td><td><code>null</code> until the cart becomes an order.</td></tr><tr><td><code>additional</code></td><td>object</td><td>Extra stored data, usually <code>null</code>.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>Before the address step runs, the response is <code>[]</code>.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Re-render the checkout review step</strong> — read both addresses back after a page reload without re-asking the shopper.</li><li><strong>Confirm &quot;ship to billing&quot; took effect</strong> — with <code>useForShipping</code> sent as <code>true</code>, two rows come back holding the same details.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Split the array by <code>addressType</code></strong> — both rows live in one list, so a page rendering <code>[0]</code> as billing will be wrong whenever the order differs.</li><li><strong>Do not read <code>useForShipping</code> from this payload</strong> — it reflects the stored row, not the flag you sent, and is <code>false</code> on both rows.</li><li><strong>Treat <code>[]</code> as &quot;step not done&quot;</strong> — it is a normal state before the address is saved, not an error.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/checkout/set-shipping-address.html">Set Shipping Address</a> — the same call with a separate delivery address</li><li><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Billing Address</a> — save both checkout addresses in one call</li><li><a href="/api/rest-api/shop/checkout/get-shipping-methods.html">Get Shipping Methods</a> — the rates available for the saved address</li></ul><p>This endpoint returns only the addresses attached to the current checkout, one row per type. It is not the customer&#39;s address book — read that with <a href="/api/rest-api/shop/customers/get-customer-addresses.html">Get Customer Addresses</a>.</p>',17)]))}const g=t(a,[["render",r]]);export{u as __pageData,g as default};
